content.css:
.dateRangeSlicer {
  position: relative;
  display: flex;
  align-items: center;
  width: 100%;
  height: 100%;
  box-sizing: border-box;
  font-family: "Segoe UI", sans-serif;
  color: var(--drs-fg, #FFFFFF);
  --drs-bg: #142436;
  --drs-fg: #FFFFFF;
  --drs-border: #2C4A6B;
  --drs-accent: #378ADD;
  --drs-radius: 3px;
  --drs-border-width: 1px;
  --drs-label-size: 12px;
}
/* 标头与触发器的布局 */
.drs-layout-top {
  flex-direction: column;
  align-items: stretch;
  justify-content: flex-start;
  gap: 4px;
}
.drs-layout-left {
  flex-direction: row;
  align-items: center;
  justify-content: flex-start;
  gap: 6px;
}
.drs-header {
  display: flex;
  flex: 0 0 auto;
  align-items: center;
  min-width: 0;
}
.drs-label {
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  line-height: 1.2;
}
/* ---------- 自绘下拉触发器（div） ---------- */
.drs-trigger {
  flex: 1 1 auto;
  min-width: 0;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 6px;
  height: 30px;
  box-sizing: border-box;
  padding: 0 8px;
  background: var(--drs-bg);
  border: var(--drs-border-width) solid var(--drs-border);
  border-radius: var(--drs-radius);
  color: var(--drs-fg);
  font-family: "Segoe UI", sans-serif;
  font-size: 12px;
  cursor: pointer;
  outline: none;
  user-select: none;
  transition: border-color 0.15s ease, box-shadow 0.15s ease;
}
.drs-trigger:hover {
  border-color: var(--drs-accent);
}
.drs-trigger.active {
  border-color: var(--drs-accent);
  box-shadow: 0 0 0 1px var(--drs-accent) inset;
}
.drs-trigger-text {
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  flex: 1 1 auto;
  min-width: 0;
}
.drs-trigger-arrow {
  flex: 0 0 auto;
  font-size: 10px;
  line-height: 1;
  color: var(--drs-fg);
}
/* ---------- 自绘下拉大面板（div，绝对定位浮在触发器下方，2 列网格） ---------- */
.drs-popup {
  position: absolute;
  left: 0;
  top: 100%;
  margin-top: 4px;
  min-width: 240px;
  max-width: 100vw;
  box-sizing: border-box;
  padding: 12px;
  background: var(--drs-list-bg, #0A1428);
  border: 1px solid var(--drs-border);
  border-radius: var(--drs-radius);
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.55);
  overflow-y: auto;
  z-index: 9999;
}
.drs-popup.drs-popup-up {
  top: auto;
  bottom: 100%;
  margin-top: 0;
  margin-bottom: 4px;
}
.drs-popup-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px;
}
.drs-option {
  display: flex;
  align-items: center;
  justify-content: center;
  height: 32px;
  padding: 0 8px;
  color: var(--drs-list-fg, #FFFFFF);
  font-size: 12px;
  text-align: center;
  cursor: pointer;
  white-space: nowrap;
  border-radius: var(--drs-radius);
  background: rgba(255, 255, 255, 0.03);
  /* hover 默认只变字色、不动背景（背景由 --drs-list-hover-bg 控制，默认透明） */
  transition: color 0.12s ease, background-color 0.12s ease, border-color 0.12s ease, box-shadow 0.12s ease;
}
.drs-option:hover {
  color: var(--drs-list-hover-fg, #B4B2A9);
  background: var(--drs-list-hover-bg, rgba(255, 255, 255, 0.05));
}
.drs-option.active {
  background: rgba(55, 138, 221, 0.18);
  color: var(--drs-accent);
  font-weight: 600;
  border: 1px solid var(--drs-accent);
  box-shadow: 0 0 8px rgba(55, 138, 221, 0.25);
}
.drs-option.active:hover {
  background: rgba(55, 138, 221, 0.22);
}
/* 选项数为奇数时，最后一个自动占满整行居中 */
.drs-popup-grid > .drs-option:nth-last-child(1):nth-child(odd) {
  grid-column: 1 / -1;
}
